SELECT ua.id,
ua.user_id,
ua.booklist_id,
ua.type,
ua.stay_time,
ua.create_time
FROM user_action ua


        AND ua.user_id = #{userId}


        AND ua.booklist_id = #{booklistId}


        AND ua.type = #{type}



    LIMIT #{current},#{size}

SELECT COUNT(*)
FROM user_action ua


        AND ua.user_id = #{userId}


        AND ua.booklist_id = #{booklistId}


        AND ua.type = #{type}
